namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.Entities;

/// <summary>
///     Entity representing a telemetry reading that supports an alert.
/// </summary>
public class AlertEvidence
{
    private AlertEvidence()
    {
    }

    /// <summary>
    ///     Initializes a new instance of the <see cref="AlertEvidence"/> class.
    /// </summary>
    /// <param name="deviceId">The device that captured the reading.</param>
    /// <param name="readingId">The reading identifier generated by the device firmware.</param>
    public AlertEvidence(Guid deviceId, Guid readingId)
    {
        DeviceId = deviceId;
        ReadingId = readingId;
    }

    /// <summary>Gets the device that captured the reading.</summary>
    public Guid DeviceId { get; private set; }

    /// <summary>Gets the reading identifier generated by the device firmware.</summary>
    public Guid ReadingId { get; private set; }
}
